/**
 * generated by stackra gen from the panel's built-in slots, the resources' pages and the Dashboard
 * documents — do not edit
 * Purpose: the panel slots a widget may name, with their place types; imported only as
 *          `#stackra/slots`.
 * Boundary: data; there is no zones or slots package. Every slot has a place that limits displays
 *           and sizes: Band (KPIs only), Grid (12 columns), Aside, Tabs, Banner, Checklist. The
 *           home dashboard has Header (Band) and Main (Grid); there is no Footer, because order and
 *           size already express it in a grid. Each resource page and each Dashboard document
 *           publishes its own slots, so a host module places a widget without editing the page.
 * Runtime: isomorphic
 */
import { Place, slots } from "@stackra/panel";

/**
 * `Slots.Dashboard.Header` holds OrderKpisWidget and `Slots.Dashboard.Main` LowStockWidget and the
 * loyalty kit's PointsIssuedWidget; AwaitingPaymentWidget has no slot (the Sales overview dashboard
 * places it).
 */
export const Slots = slots({
  Dashboard: { Header: Place.Band, Main: Place.Grid },
  Shell: { Banner: Place.Banner, Checklist: Place.Checklist },
  Orders: {
    SalesOverview: { Header: Place.Band, Main: Place.Grid },
    Order: {
      List: { Header: Place.Band, Footer: Place.Grid },
      View: { Header: Place.Band, Aside: Place.Aside, Tabs: Place.Tabs, Footer: Place.Grid },
    },
  },
  Catalogue: {
    Product: {
      List: { Header: Place.Band, Footer: Place.Grid },
      View: { Header: Place.Band, Aside: Place.Aside, Tabs: Place.Tabs, Footer: Place.Grid },
      Edit: { Aside: Place.Aside },
    },
  },
  // from @acme/loyalty-kit's resource, which this member hosts
  LoyaltyKit: {
    LoyaltyAccount: {
      List: { Header: Place.Band, Footer: Place.Grid },
      View: { Header: Place.Band, Aside: Place.Aside, Tabs: Place.Tabs, Footer: Place.Grid },
    },
  },
});
